/* =====================================================================
   Policy Tracker – database script
   Creates PolicyTrackerDB, its tables, and loads the data from the Excel
   tracker (policies, broker statements Mar–Sep 2026, bank payouts).
   Safe to run again: tables are created only if missing, data is loaded
   only when the Users table is empty.
   ===================================================================== */
IF DB_ID(N'PolicyTrackerDB') IS NULL
    CREATE DATABASE PolicyTrackerDB;
GO
USE PolicyTrackerDB;
GO

IF OBJECT_ID(N'dbo.Roles', N'U') IS NULL
CREATE TABLE dbo.Roles (
    Id   INT          NOT NULL CONSTRAINT PK_Roles PRIMARY KEY,
    Name NVARCHAR(50) NOT NULL
);
GO

IF OBJECT_ID(N'dbo.Users', N'U') IS NULL
CREATE TABLE dbo.Users (
    Id               INT IDENTITY(1,1) NOT NULL CONSTRAINT PK_Users PRIMARY KEY,
    FirstName        NVARCHAR(100) NOT NULL,
    LastName         NVARCHAR(100) NULL,
    EmailAddress     NVARCHAR(150) NOT NULL,
    PasswordHash     NVARCHAR(200) NOT NULL,
    MobileNo         NVARCHAR(20)  NULL,
    RoleId           INT NOT NULL CONSTRAINT FK_Users_Roles REFERENCES dbo.Roles(Id),
    IsActive         BIT NOT NULL CONSTRAINT DF_Users_IsActive DEFAULT (1),
    CreatedBy        INT NOT NULL,
    CreatedDate      DATETIME NOT NULL CONSTRAINT DF_Users_CreatedDate DEFAULT (GETDATE()),
    LastModifiedBy   INT NULL,
    LastModifiedDate DATETIME NULL,
    DeletedBy        INT NULL,
    DeletedDate      DATETIME NULL
);
GO
IF NOT EXISTS (SELECT 1 FROM sys.indexes WHERE name = N'UX_Users_EmailAddress')
    CREATE UNIQUE INDEX UX_Users_EmailAddress ON dbo.Users(EmailAddress) WHERE DeletedDate IS NULL;
GO

IF OBJECT_ID(N'dbo.Brokers', N'U') IS NULL
CREATE TABLE dbo.Brokers (
    Id               INT IDENTITY(1,1) NOT NULL CONSTRAINT PK_Brokers PRIMARY KEY,
    Name             NVARCHAR(150) NOT NULL,
    PosCode          NVARCHAR(50)  NULL,
    PosName          NVARCHAR(150) NULL,
    SalesManager     NVARCHAR(150) NULL,
    ContactNo        NVARCHAR(20)  NULL,
    EmailAddress     NVARCHAR(150) NULL,
    TdsRate          DECIMAL(18,2) NOT NULL CONSTRAINT DF_Brokers_TdsRate DEFAULT (5),
    IsActive         BIT NOT NULL CONSTRAINT DF_Brokers_IsActive DEFAULT (1),
    CreatedBy        INT NOT NULL,
    CreatedDate      DATETIME NOT NULL CONSTRAINT DF_Brokers_CreatedDate DEFAULT (GETDATE()),
    LastModifiedBy   INT NULL,
    LastModifiedDate DATETIME NULL,
    DeletedBy        INT NULL,
    DeletedDate      DATETIME NULL
);
GO

IF OBJECT_ID(N'dbo.InsuranceCompanies', N'U') IS NULL
CREATE TABLE dbo.InsuranceCompanies (
    Id               INT IDENTITY(1,1) NOT NULL CONSTRAINT PK_InsuranceCompanies PRIMARY KEY,
    Name             NVARCHAR(200) NOT NULL,
    ShortName        NVARCHAR(50)  NULL,
    IsActive         BIT NOT NULL CONSTRAINT DF_InsuranceCompanies_IsActive DEFAULT (1),
    CreatedBy        INT NOT NULL,
    CreatedDate      DATETIME NOT NULL CONSTRAINT DF_InsuranceCompanies_CreatedDate DEFAULT (GETDATE()),
    LastModifiedBy   INT NULL,
    LastModifiedDate DATETIME NULL,
    DeletedBy        INT NULL,
    DeletedDate      DATETIME NULL
);
GO

IF OBJECT_ID(N'dbo.Categories', N'U') IS NULL
CREATE TABLE dbo.Categories (
    Id               INT IDENTITY(1,1) NOT NULL CONSTRAINT PK_Categories PRIMARY KEY,
    Name             NVARCHAR(100) NOT NULL,
    DefaultPoints    DECIMAL(18,2) NULL,
    IsMotor          BIT NOT NULL CONSTRAINT DF_Categories_IsMotor DEFAULT (0),
    IsActive         BIT NOT NULL CONSTRAINT DF_Categories_IsActive DEFAULT (1),
    CreatedBy        INT NOT NULL,
    CreatedDate      DATETIME NOT NULL CONSTRAINT DF_Categories_CreatedDate DEFAULT (GETDATE()),
    LastModifiedBy   INT NULL,
    LastModifiedDate DATETIME NULL,
    DeletedBy        INT NULL,
    DeletedDate      DATETIME NULL
);
GO

IF OBJECT_ID(N'dbo.PointsGrids', N'U') IS NULL
CREATE TABLE dbo.PointsGrids (
    Id               INT IDENTITY(1,1) NOT NULL CONSTRAINT PK_PointsGrids PRIMARY KEY,
    BrokerId         INT NOT NULL CONSTRAINT FK_PointsGrids_Brokers REFERENCES dbo.Brokers(Id),
    CategoryId       INT NOT NULL CONSTRAINT FK_PointsGrids_Categories REFERENCES dbo.Categories(Id),
    AgeFrom          INT NOT NULL,
    AgeTo            INT NOT NULL,
    Points           DECIMAL(18,2) NOT NULL,
    IsActive         BIT NOT NULL CONSTRAINT DF_PointsGrids_IsActive DEFAULT (1),
    CreatedBy        INT NOT NULL,
    CreatedDate      DATETIME NOT NULL CONSTRAINT DF_PointsGrids_CreatedDate DEFAULT (GETDATE()),
    LastModifiedBy   INT NULL,
    LastModifiedDate DATETIME NULL,
    DeletedBy        INT NULL,
    DeletedDate      DATETIME NULL
);
GO

IF OBJECT_ID(N'dbo.Policies', N'U') IS NULL
CREATE TABLE dbo.Policies (
    Id                  INT IDENTITY(1,1) NOT NULL CONSTRAINT PK_Policies PRIMARY KEY,
    BrokerId            INT NOT NULL CONSTRAINT FK_Policies_Brokers REFERENCES dbo.Brokers(Id),
    BusinessType        NVARCHAR(30)  NULL,
    CategoryId          INT NULL CONSTRAINT FK_Policies_Categories REFERENCES dbo.Categories(Id),
    InsuranceCompanyId  INT NULL CONSTRAINT FK_Policies_InsuranceCompanies REFERENCES dbo.InsuranceCompanies(Id),
    ProductPlan         NVARCHAR(200) NULL,
    CustomerName        NVARCHAR(200) NOT NULL,
    MobileNo            NVARCHAR(20)  NULL,
    EmailAddress        NVARCHAR(150) NULL,
    EldestAge           INT NULL,
    SumInsured          DECIMAL(18,2) NULL,
    PolicyNo            NVARCHAR(100) NULL,
    PreviousPolicyNo    NVARCHAR(100) NULL,
    RenewalRefNo        NVARCHAR(100) NULL,
    VehicleNo           NVARCHAR(30)  NULL,
    StartDate           DATETIME NULL,
    ExpiryDate          DATETIME NULL,
    OdPremium           DECIMAL(18,2) NULL,
    TpPremium           DECIMAL(18,2) NULL,
    NetPremium          DECIMAL(18,2) NULL,
    GstAmount           DECIMAL(18,2) NULL,
    IndicativePremium   DECIMAL(18,2) NULL,
    PointsOd            DECIMAL(18,2) NULL,
    PointsTp            DECIMAL(18,2) NULL,
    PointsNet           DECIMAL(18,2) NULL,
    RenewalStatus       NVARCHAR(30)  NULL,
    LostReason          NVARCHAR(50)  NULL,
    QuoteSentOn         DATETIME NULL,
    QuoteDetails        NVARCHAR(500) NULL,
    RenewedOn           DATETIME NULL,
    RenewedPolicyId     INT NULL,
    RenewedFromPolicyId INT NULL,
    PaymentMode         NVARCHAR(30)  NULL,
    ChequeNo            NVARCHAR(50)  NULL,
    BankName            NVARCHAR(150) NULL,
    UtrNo               NVARCHAR(100) NULL,
    AmountPaid          DECIMAL(18,2) NULL,
    PaymentDate         DATETIME NULL,
    SubmittedToBrokerOn DATETIME NULL,
    BrokerStaff         NVARCHAR(100) NULL,
    ProofRef            NVARCHAR(300) NULL,
    PolicyCopyReceived  BIT NOT NULL CONSTRAINT DF_Policies_PolicyCopyReceived DEFAULT (0),
    Remarks             NVARCHAR(2000) NULL,
    IsActive            BIT NOT NULL CONSTRAINT DF_Policies_IsActive DEFAULT (1),
    CreatedBy           INT NOT NULL,
    CreatedDate         DATETIME NOT NULL CONSTRAINT DF_Policies_CreatedDate DEFAULT (GETDATE()),
    LastModifiedBy      INT NULL,
    LastModifiedDate    DATETIME NULL,
    DeletedBy           INT NULL,
    DeletedDate         DATETIME NULL
);
GO
IF NOT EXISTS (SELECT 1 FROM sys.indexes WHERE name = N'IX_Policies_Broker_Expiry')
    CREATE INDEX IX_Policies_Broker_Expiry ON dbo.Policies(BrokerId, ExpiryDate) WHERE DeletedDate IS NULL;
IF NOT EXISTS (SELECT 1 FROM sys.indexes WHERE name = N'IX_Policies_PolicyNo')
    CREATE INDEX IX_Policies_PolicyNo ON dbo.Policies(PolicyNo);
GO

IF OBJECT_ID(N'dbo.StatementLines', N'U') IS NULL
CREATE TABLE dbo.StatementLines (
    Id               INT IDENTITY(1,1) NOT NULL CONSTRAINT PK_StatementLines PRIMARY KEY,
    BrokerId         INT NOT NULL CONSTRAINT FK_StatementLines_Brokers REFERENCES dbo.Brokers(Id),
    StatementMonth   DATETIME NOT NULL,
    StartDate        DATETIME NULL,
    ExpiryDate       DATETIME NULL,
    SalesManager     NVARCHAR(150) NULL,
    PosName          NVARCHAR(150) NULL,
    PosCode          NVARCHAR(50)  NULL,
    CustomerName     NVARCHAR(200) NULL,
    InsuranceCompany NVARCHAR(200) NULL,
    Product          NVARCHAR(200) NULL,
    PolicyNo         NVARCHAR(100) NULL,
    OdPremium        DECIMAL(18,2) NULL,
    TpPremium        DECIMAL(18,2) NULL,
    NetPremium       DECIMAL(18,2) NULL,
    GstAmount        DECIMAL(18,2) NULL,
    PointsOd         DECIMAL(18,2) NULL,
    PointsTp         DECIMAL(18,2) NULL,
    PointsNet        DECIMAL(18,2) NULL,
    Value            DECIMAL(18,2) NOT NULL,
    Remarks          NVARCHAR(500) NULL,
    PolicyId         INT NULL CONSTRAINT FK_StatementLines_Policies REFERENCES dbo.Policies(Id),
    MatchStatus      NVARCHAR(30)  NULL,
    ImportBatch      NVARCHAR(100) NULL,
    CreatedBy        INT NOT NULL,
    CreatedDate      DATETIME NOT NULL CONSTRAINT DF_StatementLines_CreatedDate DEFAULT (GETDATE()),
    LastModifiedBy   INT NULL,
    LastModifiedDate DATETIME NULL
);
GO
IF NOT EXISTS (SELECT 1 FROM sys.indexes WHERE name = N'IX_StatementLines_Broker_Month')
    CREATE INDEX IX_StatementLines_Broker_Month ON dbo.StatementLines(BrokerId, StatementMonth);
IF NOT EXISTS (SELECT 1 FROM sys.indexes WHERE name = N'IX_StatementLines_PolicyId')
    CREATE INDEX IX_StatementLines_PolicyId ON dbo.StatementLines(PolicyId);
GO

IF OBJECT_ID(N'dbo.Payouts', N'U') IS NULL
CREATE TABLE dbo.Payouts (
    Id               INT IDENTITY(1,1) NOT NULL CONSTRAINT PK_Payouts PRIMARY KEY,
    BrokerId         INT NOT NULL CONSTRAINT FK_Payouts_Brokers REFERENCES dbo.Brokers(Id),
    StatementMonth   DATETIME NULL,
    ReceivedOn       DATETIME NULL,
    AmountReceived   DECIMAL(18,2) NOT NULL,
    PaidByFirm       NVARCHAR(150) NULL,
    TdsRate          DECIMAL(18,2) NULL,
    Remarks          NVARCHAR(500) NULL,
    CreatedBy        INT NOT NULL,
    CreatedDate      DATETIME NOT NULL CONSTRAINT DF_Payouts_CreatedDate DEFAULT (GETDATE()),
    LastModifiedBy   INT NULL,
    LastModifiedDate DATETIME NULL,
    DeletedBy        INT NULL,
    DeletedDate      DATETIME NULL
);
GO

IF NOT EXISTS (SELECT 1 FROM dbo.Users)
BEGIN
    SET NOCOUNT ON;
    BEGIN TRANSACTION;
    SET IDENTITY_INSERT dbo.Users ON;
    SET IDENTITY_INSERT dbo.Users OFF;
    SET IDENTITY_INSERT dbo.Brokers ON;
    SET IDENTITY_INSERT dbo.Brokers OFF;
    SET IDENTITY_INSERT dbo.Categories ON;
    SET IDENTITY_INSERT dbo.Categories OFF;
    SET IDENTITY_INSERT dbo.InsuranceCompanies ON;
    SET IDENTITY_INSERT dbo.InsuranceCompanies OFF;

    SET IDENTITY_INSERT dbo.Policies ON;
    SET IDENTITY_INSERT dbo.Policies OFF;



    COMMIT TRANSACTION;
END
GO
